// serializeArray and serializeObject receive convertToSerializedForm as a parameter, because
// it is defined after them and calls them in turn.
type ConvertToSerializedForm = (
  value: any,
  metadata: AstroComponentMetadata | Record<string, any>,
  parents: WeakSet<any>
) => [ValueOf<typeof PROP_TYPE>, any] | [ValueOf<typeof PROP_TYPE>];

const serializeArray = (
  value: any[],
  convert: ConvertToSerializedForm,
  metadata: AstroComponentMetadata | Record<string, any> = {},
  parents = new WeakSet<any>()
): any[] => {
  if (parents.has(value)) {
    throw new Error(`Cyclic reference detected while serializing props for <${metadata.displayName} client:${metadata.hydrate}>!

Cyclic references cannot be safely serialized for client-side usage. Please remove the cyclic reference.`);
  }

      if (value !== null && typeof value === "object") {
        return [
          PROP_TYPE.Value,
          serializeObject(value, convertToSerializedForm, metadata, parents),
        ];
      }
      if (value === Number.POSITIVE_INFINITY) {
        return [PROP_TYPE.Infinity, 1];
      }
      if (value === Number.NEGATIVE_INFINITY) {
        return [PROP_TYPE.Infinity, -1];
      }
      if (value === undefined) {
        return [PROP_TYPE.Value];
      }
      return [PROP_TYPE.Value, value];
    }
  }
};

export const serializeProps = (
  props: any,
  metadata?: AstroComponentMetadata
) => {
  const serialized = JSON.stringify(
    serializeObject(props, convertToSerializedForm, metadata)
  );
  return serialized;
};
